    def raise_dialog(self, title, message, description, needretry=False):
        try:
            msg = QMessageBox(self)
            msg.setText(message)
            msg.setInformativeText(description)
            msg.setWindowTitle(title)
            if needretry:
                self.raise_errorflag()
                msg.setStandardButtons(QMessageBox.Retry | QMessageBox.Cancel)
                self.downloadACTaskThread.quit()
                self.downloadACTaskThread.terminate()
                self.downloadACTaskThread.wait()
            else:
                msg.setStandardButtons(QMessageBox.Close)
                self.downloadACTaskThread.quit()
            retval = msg.exec()
            if retval == QMessageBox.Retry:
                self.errorflag = False
                self.define_thread()
                self.start_thread()
            elif retval == QMessageBox.Cancel or QMessageBox.Close:
                self.cancel_operation()
                self.retstatus = 'ERROR'
                self.close()

        except Exception as msg:
            logging.debug('error' + msg)

    def raise_errorflag(self):
        self.errorflag = True

    def update_dialog_title(self,index : int,status : downloadACDialogThread.downloadDialogStatus):
        index = f"{index+1}/{len(self.acQueueListManager.queue_list)}"
        print(index)

        if status == downloadDialogStatus.analyzing:
            self.dialogLabel.setText(f"Analyzing course {index}")

        if status == downloadDialogStatus.downloading:
            self.dialogLabel.setText(f"Downloading course {index}")

        if status == downloadDialogStatus.processing:
            self.dialogLabel.setText(f"Processing course {index}")

        if status == downloadDialogStatus.dlassets_extracting:
            self.dialogLabel.setText(f"Downloading assets + Extracting\n course {index}")

        if status == downloadDialogStatus.extracting:
            self.dialogLabel.setText(f"Extracting course {index}")

        if status == downloadDialogStatus.processing_media:
            self.dialogLabel.setText(f"Processing media course {index}\n~= 20min for 1.5 hour video/audio")

        if status == downloadDialogStatus.merging:
            self.dialogLabel.setText(f"Merging course {index}")

        if status == downloadDialogStatus.cleanup:
            self.dialogLabel.setText(f"Cleaning course {index}")

        print('set dialog label')
        QtWidgets.QApplication.processEvents()

    # CANCEL OPERATION HANDLER
    def cancel_button_action(self):
        cancel_msg = "Are you sure you want to cancel the operation?"
        reply = QMessageBox()
        reply.setText(cancel_msg)
        reply.setIcon(QMessageBox.Question)
        reply.setWindowTitle("Cancel download")
        reply.setStandardButtons(QMessageBox.Cancel | QMessageBox.No)
        reply.setDefaultButton(QMessageBox.No)
        reply = reply.exec_()

        if reply == QMessageBox.Cancel:
            self.raise_errorflag()
            self.downloadACTaskThread.quit()
            self.downloadACTaskThread.terminate()
            self.downloadACTaskThread.wait()
            self.cancel_operation()
            self.retstatus = 'CANCEL'
            self.close()

    def cancel_operation(self):
        """
        In this operation remove all folders from QueueList.
        :return:
        """
        for course in self.downloadACTaskThread.acQueueManager.queue_list:
            try:
                self.downloadACTaskThread.course_cleanup(course)
            except:
                pass
            finally:
                course.status = 1
                self.downloadACTaskThread.acQueueManager.update_ac_course_object(course)

        self.downloadACTaskThread.quit()
        self.downloadACTaskThread.terminate()
        self.downloadACTaskThread.wait()
        # self.acQueueListManager.cancel_and_remove_files()

    # PROGRESS BAR CONTROLLER
    def set_progressbar_max_value(self,value):
        self.progressBar.setMaximum(round(value))

    def update_progressbar_value(self,value):
        self.progressBar.setValue(round(value))

    def add_to_progressbar_current_value(self,value):
        self.progressBar.setValue(
            round(value) + self.progressBar.value()
        )

    def devide_progressbar_to(self,to):
        """
        This functions times progressbar max value to "to" input
        :param to:
        :return:
        """
        self.set_progressbar_max_value(
            self.progressBar.maximum() * int(to)
        )

    def fill_progressbar_devide(self,to):
        """
        This function fills "1/to" * maximum of progressbar.
        :param to:
        :return:
        """
        self.add_to_progressbar_current_value(
            self.progressBar.maximum()/to
        )

    # COUNTERS CONTROLLER
    def reset_all_lcd_counters(self):
        self.downloadedLCDNumber.display(0)
        self.extractedLCDNumber.display(0)
        self.downloadedAssetsLCDNumber.display(0)
        self.convertedLCDNumber.display(0)

    def increase_downloaded_lcd_number(self,add=1):
        self.downloadedLCDNumber.display(self.downloadedLCDNumber.intValue()+add)

    def increase_exctracted_lcd_number(self, add=1):
        self.extractedLCDNumber.display(self.extractedLCDNumber.intValue() + add)

    def increase_downloaded_assets_lcd_number(self, add=1):
        self.downloadedAssetsLCDNumber.display(self.downloadedAssetsLCDNumber.intValue() + add)

    def increase_converted_lcd_number(self, add=1):
        self.convertedLCDNumber.display(self.convertedLCDNumber.intValue() + add)


    # THREAD CONTROLLER
    def download_finished(self):
        if not self.errorflag:
            self.downloadACTaskThread.quit()
            self.downloadACTaskThread.terminate()
            self.downloadACTaskThread.wait()
            failed = []
            for item in self.downloadACTaskThread.acQueueManager.queue_list:
                if item.status not in [acCourseStatus.finished, acCourseStatus.cleanedup]:  # IF COURSE IS NOT FINISHED OR CLEANUP
                    failed.append(item)
                    print('added item failed : ',item.filename,item.status)
            if failed:
                #TODO : MOVE REMOVE FAILED FILES HERE.
                msg = QMessageBox(self)
                message = f"Failed to download or process {len(failed)} item(s) from queue"
                msg.setText(message)
                msg.setInformativeText("".join(f'{index+1} - {item.filename}\n' for index, item in enumerate(failed)))
                msg.setWindowTitle('Completed downloading meetings.')
                msg.setStandardButtons(QMessageBox.Ok)
                msg.exec_()
                self.downloadACTaskThread.acQueueManager.remove_failed_files()
            self.retstatus = 'COMPLETED'
            self.close()

    def define_thread(self):
        self.downloadACTaskThread = downloadACDialogThread.downloadACThread(acbrowser=self.acBrowser, queuemanager=self.acQueueListManager)
        self.downloadACTaskThread.reset_all_lcd_counters.connect(self.reset_all_lcd_counters)
        self.downloadACTaskThread.increase_downloaded_lcd_number.connect(self.increase_downloaded_lcd_number)
        self.downloadACTaskThread.increase_exctracted_lcd_number.connect(self.increase_exctracted_lcd_number)
        self.downloadACTaskThread.increase_downloaded_assets_lcd_number.connect(self.increase_downloaded_assets_lcd_number)
        self.downloadACTaskThread.increase_converted_lcd_number.connect(self.increase_converted_lcd_number)

        self.downloadACTaskThread.update_progress_bar_value.connect(self.update_progressbar_value)
        self.downloadACTaskThread.max_progress_bar_value.connect(self.set_progressbar_max_value)
        self.downloadACTaskThread.add_to_progressbar_current_value.connect(self.add_to_progressbar_current_value)
        self.downloadACTaskThread.devide_progressbar_to.connect(self.devide_progressbar_to)
        self.downloadACTaskThread.fill_progressbar_devide.connect(self.fill_progressbar_devide)

        self.downloadACTaskThread.update_dialog_title.connect(self.update_dialog_title)
        self.downloadACTaskThread.raise_dialog.connect(self.raise_dialog)
        self.downloadACTaskThread.raise_errorflag.connect(self.raise_errorflag)

        self.downloadACTaskThread.finished.connect(self.download_finished)

    def start_thread(self):
        try:
            self.downloadACTaskThread.start()
        except Exception as msg:
            print(msg)


